/** Runner-owned write/read commands keep the genuine preimage bytes outside the source tree. */
class NativeSortedNamesSerializationProbe {
	public static void main(String[] args) throws Exception {
		Path path = Path.of(args[1]);
		if (args[0].equals("write")) {
			try (ObjectOutputStream output = new ObjectOutputStream(Files.newOutputStream(path))) {
				output.writeObject(NativeSortedNamesCompatibilityTest.detachedRow());
			}
		} else if (args[0].equals("read")) {
			try (ObjectInputStream input = new ObjectInputStream(Files.newInputStream(path))) {
				BindingSet restored = (BindingSet) input.readObject();
				if (NativeSortedNamesCompatibilityTest.comparator()
						.compare(
								NativeSortedNamesCompatibilityTest.detachedRow(), restored) != 0) {
					throw new AssertionError("Detached preimage mapping changed");
				}
			}
		} else {
			throw new IllegalArgumentException("Expected write or read");
		}
		System.out.println("mode=" + args[0] + " bytes=" + Files.size(path) + " uid="
				+ ObjectStreamClass.lookup(NativeProjectedBindingSet.class).getSerialVersionUID());
	}
}
